import{_ as t}from"./chunks/karin_connect.x7uBhTYg.js";import{_ as b,C as i,c as u,o as k,j as e,G as l,bc as c,a as h}from"./chunks/framework.CYYFJByd.js";const _="/web/karin_start.png",n="/web/napcat_webui.png",r="/web/napcat_webui_client_new.png",d="/web/napcat_webui_client_save.png",m="/web/karin_webui_login.png",g="/web/karin_webui_client_new.png",w="/web/karin_webui_websocket_save.png",K=JSON.parse('{"title":"目录","description":"","frontmatter":{},"headers":[],"relativePath":"install/platform.md","filePath":"install/platform.md","lastUpdated":1744301488000}'),f={name:"install/platform.md"};function S(N,a,v,C,P,T){const s=i("NolebasePageProperties"),o=i("Pill"),p=i("NolebaseGitChangelog");return k(),u("div",null,[a[1]||(a[1]=e("h1",{id:"目录",tabindex:"-1"},[h("目录 "),e("a",{class:"header-anchor",href:"#目录","aria-label":'Permalink to "目录"'},"​")],-1)),l(s),a[2]||(a[2]=c('<nav class="table-of-contents"><ul><li><a href="#接入适配器">接入适配器</a></li><li><a href="#基本配置信息">基本配置信息</a><ul><li><a href="#默认配置一览">默认配置一览</a></li></ul></li><li><a href="#websocket-连接说明">WebSocket 连接说明</a><ul><li><a href="#正向-websocket-vs-反向-websocket">正向 WebSocket vs 反向 WebSocket</a></li></ul></li><li><a href="#实战配置-以-napcat-为例">实战配置：以 NapCat 为例</a><ul><li><a href="#配置步骤">配置步骤</a></li><li><a href="#napcat-具体配置">NapCat 具体配置</a></li></ul></li><li><a href="#实战配置二-karin-主动出击-napcat">实战配置二: Karin 主动出击 NapCat</a><ul><li><a href="#配置步骤-1">配置步骤</a></li></ul></li></ul></nav><h2 id="接入适配器" tabindex="-1">接入适配器 <a class="header-anchor" href="#接入适配器" aria-label="Permalink to &quot;接入适配器&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">温馨提示</p><p>支持所有符合 <code>OneBot11</code> 标准的平台 包括但不限于以下<br> 以下排名不分先后 感谢所有前行者的无私奉献！</p></div>',3)),e("ul",null,[e("li",null,[l(o,{name:"NapCat",link:"https://www.napcat.wiki/"})]),e("li",null,[l(o,{name:"LLOneBot",link:"https://llonebot.github.io/zh-CN/"})]),e("li",null,[l(o,{name:"Lagrange.OneBot",link:"https://lagrangedev.github.io/Lagrange.Doc/Lagrange.OneBot/"})]),e("li",null,[l(o,{name:"Gensokyo",link:"https://github.com/Hoshinonyaruko/Gensokyo"})]),e("li",null,[l(o,{name:"OneBots",link:"https://github.com/lc-cn/onebots"})]),a[0]||(a[0]=e("li",null,"更多适配器正在路上... 🚀",-1))]),a[3]||(a[3]=c('<h2 id="基本配置信息" tabindex="-1">基本配置信息 <a class="header-anchor" href="#基本配置信息" aria-label="Permalink to &quot;基本配置信息&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">温馨提示</p><p>本文适用于<code>1.4.7+</code>版本<br> 启动 Karin 后，你将看到一个充满魔法的控制台界面 ✨</p></div><h3 id="默认配置一览" tabindex="-1">默认配置一览 <a class="header-anchor" href="#默认配置一览" aria-label="Permalink to &quot;默认配置一览&quot;">​</a></h3><ul><li>HTTP 服务端口: <code>7777</code></li><li>WebSocket 服务端口: <code>7777</code> (与 HTTP 端口共用)</li><li>HTTP Token: 自动生成的 6 位随机大小写字母</li><li>WebSocket Token: 自动生成的 6 位随机大小写字母</li><li>Web 控制台地址: <code>http://127.0.0.1:7777/web</code></li><li>OneBot11 API 接入点<code>(任选其一)</code>: <ul><li>1: <code>ws://127.0.0.1:7777</code></li><li>2: <code>ws://127.0.0.1:7777/onebot/v11/ws</code></li><li>3: <code>http_post</code> <code>http://127.0.0.1:7777/onebot</code></li></ul></li></ul><p><img src="'+_+'" alt="karin_start" loading="lazy"></p><h2 id="websocket-连接说明" tabindex="-1">WebSocket 连接说明 <a class="header-anchor" href="#websocket-连接说明" aria-label="Permalink to &quot;WebSocket 连接说明&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">小贴士</p><p>让我们来了解一下 WebSocket 连接的两种模式，就像认识两个性格不同的小伙伴 🤝</p></div><h3 id="正向-websocket-vs-反向-websocket" tabindex="-1">正向 WebSocket vs 反向 WebSocket <a class="header-anchor" href="#正向-websocket-vs-反向-websocket" aria-label="Permalink to &quot;正向 WebSocket vs 反向 WebSocket&quot;">​</a></h3><p>想象一下两种不同的交友方式：</p><ul><li><p><strong>反向 WebSocket (Client 模式)</strong></p><ul><li>协议端主动出击，向 Karin 发起连接请求</li><li>Karin 作为 WebSocket 服务器(Server)静待连接</li><li>就像是协议端主动来敲 Karin 的门</li></ul></li><li><p><strong>正向 WebSocket (Server 模式)</strong></p><ul><li>Karin 主动出击，向协议端发起连接</li><li>协议端作为 WebSocket 服务器等待连接</li><li>就像是 Karin 去拜访协议端</li></ul></li></ul><p>Karin 默认开启反向 WebSocket 模式，也就是在家里等着朋友来访 🏠</p><h2 id="实战配置-以-napcat-为例" tabindex="-1">实战配置：以 NapCat 为例 <a class="header-anchor" href="#实战配置-以-napcat-为例" aria-label="Permalink to &quot;实战配置：以 NapCat 为例&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">温馨提示</p><p>开始之前，请确保已从 Karin 控制台获取到 WebSocket 鉴权 Token</p></div><h3 id="配置步骤" tabindex="-1">配置步骤 <a class="header-anchor" href="#配置步骤" aria-label="Permalink to &quot;配置步骤&quot;">​</a></h3><ol><li>启动 <code>Karin</code>，它会在 <code>7777</code> 端口开启派对 🎉</li><li>从控制台获取专属的 WebSocket 鉴权 Token</li><li>启动 <code>NapCat</code>，建立友谊</li><li>配置 <code>NapCat</code>，让它知道去哪找 <code>Karin</code></li><li>查看 <code>Karin</code> 日志，确认连接成功</li></ol><h3 id="napcat-具体配置" tabindex="-1">NapCat 具体配置 <a class="header-anchor" href="#napcat-具体配置" aria-label="Permalink to &quot;NapCat 具体配置&quot;">​</a></h3><p>首先确保你已经：</p><ul><li>安装好 <code>NapCat</code></li><li>进入 <code>NapCat</code> 的 Web 控制台</li></ul><h4 id="配置详细步骤" tabindex="-1">配置详细步骤 <a class="header-anchor" href="#配置详细步骤" aria-label="Permalink to &quot;配置详细步骤&quot;">​</a></h4><ol><li>在 <code>NapCat</code> 控制台点击<code>网络配置</code>：</li></ol><p><img src="'+n+'" alt="napcat_webui" loading="lazy"></p><ol start="2"><li>创建新连接： <ul><li>点击<code>新建</code>按钮</li><li>选择<code>WebSocket客户端</code>模式</li></ul></li></ol><p><img src="'+r+'" alt="napcat_webui_client_new" loading="lazy"></p><ol start="3"><li>填写连接信息： <ul><li>启用开关：✅ 开启</li><li>名称：<code>karin</code> <code>(支持任意名称)</code></li><li>URL：<code>ws://127.0.0.1:7777</code></li><li>鉴权 Token：填入 Karin 控制台显示的 Token</li><li>最后点击<code>保存</code></li></ul></li></ol><p><img src="'+d+'" alt="napcat_webui_client_save" loading="lazy"></p><p>如果一切顺利，切换到 Karin 控制台，你会看到这样温馨的提示：</p><p><img src="'+t+'" alt="karin_connect" loading="lazy"></p><p>恭喜你！Karin 和 NapCat 已经成功牵手啦 🎊</p><h2 id="实战配置二-karin-主动出击-napcat" tabindex="-1">实战配置二: Karin 主动出击 NapCat <a class="header-anchor" href="#实战配置二-karin-主动出击-napcat" aria-label="Permalink to &quot;实战配置二: Karin 主动出击 NapCat&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">温馨提示</p><p><code>鉴权token</code>支持不配置，但是推荐配置。</p></div><h3 id="配置步骤-1" tabindex="-1">配置步骤 <a class="header-anchor" href="#配置步骤-1" aria-label="Permalink to &quot;配置步骤&quot;">​</a></h3><ol><li>启动 <code>NapCat</code> 开启服务</li><li>配置 <code>NapCat</code> 开启端口</li><li>启动 <code>karin</code></li><li>进入 <code>Karin-webui</code> 配置 <code>WebSocket</code> 连接</li><li>配置 <code>WebSocket</code> 连接信息</li><li>保存配置</li><li>查看 <code>Karin</code> 日志，确认连接成功</li></ol><h4 id="napcat-具体配置-1" tabindex="-1">NapCat 具体配置 <a class="header-anchor" href="#napcat-具体配置-1" aria-label="Permalink to &quot;NapCat 具体配置&quot;">​</a></h4><ol><li>在 <code>NapCat</code> 控制台点击<code>网络配置</code>：</li></ol><p><img src="'+n+'" alt="napcat_webui" loading="lazy"></p><ol start="2"><li>创建新连接： <ul><li>点击<code>新建</code>按钮</li><li>选择<code>WebSocket服务器</code>模式</li></ul></li></ol><p><img src="'+r+'" alt="napcat_webui_client_new" loading="lazy"></p><ol start="3"><li>填写连接信息： <ul><li>启用开关：✅ 开启</li><li>名称：<code>karin_server</code> <code>(支持任意名称)</code></li><li>HOST: <code>无需修改 默认即可</code></li><li>Port: 3001 <code>(记住此端口 后续需要使用)</code></li><li>Token: NapCat <code>(不配置也可以的 如果配置需要记住 后续需要使用)</code></li><li>最后点击<code>保存</code></li></ul></li></ol><p><img src="'+d+'" alt="napcat_webui_client_save" loading="lazy"></p><ol start="4"><li>组合 wsUrl: <code>ws://127.0.0.1:3001</code> token: <code>NapCat</code></li></ol><h4 id="karin-具体配置" tabindex="-1">Karin 具体配置 <a class="header-anchor" href="#karin-具体配置" aria-label="Permalink to &quot;Karin 具体配置&quot;">​</a></h4><ol><li>打开 <code>Karin-webui</code><ul><li>打开 <code>http://127.0.0.1:7777/web</code> 如果更换了端口请以控制台打印为准</li><li>在登录页面输入控制台打印的 http 鉴权 token: <code>AffryQ</code></li><li>点击<code>登录</code></li></ul></li></ol><p><img src="'+m+'" alt="karin_webui_login" loading="lazy"></p><ol start="2"><li>进入 <code>Karin-webui</code> 配置 <code>WebSocket</code> 连接 <ul><li>点击 <code>配置信息</code> 进入系统配置</li><li>选择 <code>适配器</code></li><li>选择 <code>正向 WebSocket 客户端</code></li><li>点击 <code>添加</code></li></ul></li></ol><p><img src="'+g+'" alt="karin_webui_client_new" loading="lazy"></p><ol start="3"><li>填写连接信息： <ul><li>启用开关：✅ 开启</li><li>WebSocketServer 地址: <code>ws://127.0.0.1:3001</code></li><li>Token: <code>NapCat</code></li><li>最后点击右上角的<code>保存</code></li></ul></li></ol><p><img src="'+w+'" alt="karin_webui_websocket_save" loading="lazy"></p><ol start="4"><li>查看 <code>Karin</code> 日志，确认连接成功</li></ol><p><img src="'+t+'" alt="karin_connect" loading="lazy"></p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>更多接入正在编写中...</p></div>',50)),l(p)])}const x=b(f,[["render",S]]);export{K as __pageData,x as default};
